export function buildSeedanceShowcaseCases(destination: StudioDestination): HubShowcaseCase[] {
  return SEEDANCE_CASES.map(([id, title, tag, poster, video, videoHd, author, sourceUrl, aspectRatio, prompt]) => ({
    id, title, tag, poster, video, videoHd, author, sourceUrl, aspectRatio, prompt, destination,
  }));
}

export function buildGptImageShowcaseCases(destination: StudioDestination): HubShowcaseCase[] {
  return GPT_IMAGE_CASES.map(([id, title, tag, poster, author, sourceUrl, aspectRatio, prompt]) => ({
    id, title, tag, poster, author, sourceUrl, aspectRatio, prompt, destination,
  }));
}
